    op.execute(
        "ALTER TABLE credentials ALTER COLUMN revoked_at TYPE TIMESTAMP WITH TIME ZONE "
        "USING revoked_at AT TIME ZONE 'UTC'"
    )
    op.execute(
        "ALTER TABLE personas ALTER COLUMN session_state_updated_at TYPE TIMESTAMP WITH TIME ZONE "
        "USING session_state_updated_at AT TIME ZONE 'UTC'"
    )
    op.execute(
        "ALTER TABLE personas ALTER COLUMN session_state_expires_at TYPE TIMESTAMP WITH TIME ZONE "
        "USING session_state_expires_at AT TIME ZONE 'UTC'"
    )


